{ arg out=0, freq=440, amp=0.1, gate=1, cutoff=4000, rq=0.5;
    var sig;
    var env = EnvGen.ar(
        Env.perc(0.005, 0.5, curve: -4), // Quick pluck envelope
        gate: gate,
        doneAction: 2
    );
    sig = Saw.ar(freq); // Sawtooth wave for a brighter sound
    sig = RLPF.ar(sig, cutoff + (env * 2000), rq) * amp * env; // Resonant Low-Pass filter, cutoff modulated by envelope
    Out.ar(out, sig ! 2);
}
